<?php require_once __DIR__.'/../../includes/bootstrap.php';require_role('petugas');$pid=(int)($_GET['petugas_id']??0);require_selected_petugas($pid);$doc=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT d.nama_file,d.path_file FROM dokumentasi d JOIN detail_progress dp ON dp.id_detail=d.id_detail JOIN progress_harian ph ON ph.id_progress=dp.id_progress JOIN petugas p ON p.id_petugas=ph.id_petugas WHERE d.id_dokumentasi=? AND p.id_petugas=? AND p.id_user=?');$q->execute([$doc,$pid,current_user()['id_user']]);$r=$q->fetch();if(!$r){http_response_code(404);exit('Dokumentasi tidak ditemukan.');}$path=realpath(__DIR__.'/../../'.ltrim($r['path_file'],'/'));$base=realpath(__DIR__.'/../../uploads/dokumentasi');if(!$path||!$base||strpos($path,$base.DIRECTORY_SEPARATOR)!==0){http_response_code(404);exit('File tidak tersedia.');}$mime=(new finfo(FILEINFO_MIME_TYPE))->file($path);if(!in_array($mime,['image/jpeg','image/png'],true)){http_response_code(415);exit('Format file tidak didukung.');}header('Content-Type: '.$mime);header('Content-Disposition: inline; filename="'.basename($r['nama_file']).'"');header('Content-Length: '.filesize($path));readfile($path);exit;
